-- 4. Set the printed April 2026 RTA list price only where the guide states one.
-- A style the guide marks not offered is left unchanged. Distributor 210001 is Faircrest / Clark and Son.
UPDATE cabinet_dealz.distributor_skus AS faircrest_sku JOIN cabinet_dealz.cabinets AS faircrest_cabinet ON faircrest_cabinet.id = faircrest_sku.cabinetId JOIN cabinet_dealz.door_styles AS faircrest_style ON faircrest_style.id = faircrest_sku.styleId SET faircrest_sku.listPrice = CASE faircrest_style.styleCode WHEN 'CS' THEN 818.39 WHEN 'DN' THEN 764.85 WHEN 'GV' THEN 841.34 WHEN 'FS' THEN 803.09 WHEN 'MBS' THEN 803.09 WHEN 'CC' THEN 764.85 WHEN 'PS' THEN 764.85 WHEN 'WS' THEN 764.85 WHEN 'HS' THEN 1109.03 WHEN 'RH' THEN 1109.03 WHEN 'WPG' THEN 1109.03 WHEN 'NG' THEN 1109.03 ELSE faircrest_sku.listPrice END WHERE faircrest_cabinet.masterCode = '2DB24' AND faircrest_sku.distributorId = 210001 AND faircrest_style.styleCode IN ('CS', 'DN', 'GV', 'FS', 'MBS', 'CC', 'PS', 'WS', 'HS', 'RH', 'WPG', 'NG');
