-- 5. Aspen White (ASP), the raised-panel door the November 2026 edition adds.
-- Color #F4F2EC is the existing Faircrest color sheet's estimated Classic White, not a hex printed in the guide.
INSERT INTO cabinet_dealz.door_styles (distributorId, styleCode, ourName, aliasName, distributorName, doorStyle, woodSpecies, finish, color, doorSampleImageUrl, profileDescription, sourceSpecification, isFeatured, isActive)
SELECT 210001, 'ASP', 'Aspen White', 'Aspen White (Ashford)', 'Aspen White', 'Raised Panel', 'Solid Maple / Birch', 'Painted', '#F4F2EC', '/walzcraft/doors/faircrest-asp.webp',
'A traditional raised-panel door in a bright painted white.', 'Faircrest Cabinets Product Specification Guide, November 2026 Edition, door styles.', 0, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.door_styles AS existing_style WHERE existing_style.distributorId = 210001 AND existing_style.styleCode = 'ASP');

-- 6. Winchester Grey's order code is NG. Greek Villa and Designer Natural are Designer Series.
UPDATE cabinet_dealz.door_styles SET styleCode = 'NG' WHERE distributorId = 210001 AND ourName = 'Winchester Grey' AND styleCode = 'WG';
UPDATE cabinet_dealz.door_styles SET doorStyle = 'Designer Series' WHERE distributorId = 210001 AND styleCode IN ('GV', 'DN');

-- 7. Read-only check. Expect ASP present, Winchester Grey styleCode NG, and the new kitchen codes on file.
SELECT faircrest_style.styleCode, faircrest_style.ourName, faircrest_style.doorStyle FROM cabinet_dealz.door_styles AS faircrest_style WHERE faircrest_style.distributorId = 210001 AND faircrest_style.styleCode IN ('ASP', 'NG', 'GV', 'DN') ORDER BY faircrest_style.styleCode;
